public class Counter {
    static int count = 0;        // static field — shared by all instances
    String name;                  // instance field — unique per object

    Counter(String name) {
        this.name = name;
        count++;                  // all instances share this count
    }

    static int getCount() {      // static method — call without object
        // return name;           // ERROR — can't access instance variable
        return count;
    }

    // static initializer block — runs once when class loads
    static {
        System.out.println("Counter class loaded");
    }
}

Counter.getCount();              // call static method via class name
```

```java
class Animal {
    String name;
    Animal(String name) { this.name = name; }
    void speak() { System.out.println(name + " speaks"); }
}

class Dog extends Animal {
    String breed;

    Dog(String name, String breed) {
        super(name);         // calls Animal's constructor — MUST be first line
        this.breed = breed;  // 'this' disambiguates field vs parameter
    }

    Dog(String name) {
        this(name, "Unknown");  // calls Dog(name, breed) — MUST be first line
    }

    @Override
    void speak() {
        super.speak();           // calls Animal's speak()
        System.out.println("Woof!");
    }
}
```

```java
public abstract class Shape {        // abstract class — can't instantiate
    String color;

    abstract double area();          // abstract method — no body, must override

    void describe() {                // concrete method — has a body
        System.out.println("Shape: " + color + ", area=" + area());
    }
}

public class Circle extends Shape {
    double radius;

    @Override
    double area() {
        return Math.PI * radius * radius;  // must implement
    }
}

// Shape s = new Shape();  // ERROR — can't instantiate abstract class
Shape s = new Circle();    // OK — Circle is concrete
```

